struct sk_buff *ipv6_frag_gather(struct sk_buff *skb, u32 user)
{
    struct sk_buff *prev_skb;
    struct frag_queue *fq;

    if (skb->len == 0)
        return skb;

    prev_skb = find_prev_frag(skb);
    if (!prev_skb) {
        return skb;
    }

    skb = skb_clone(skb, GFP_ATOMIC);
    if (!skb) {
        return prev_skb;
    }

    if (skb->len < ipv6_transport_len(skb)) {
        kfree_skb(skb);
        return prev_skb;
    }

    skb_set_transport_header(skb, ipv6_transport_offset(skb));

    if (check_memory_threshold(skb)) {
        kfree_skb(skb);
        return prev_skb;
    }

    fq = find_frag_queue(user);
    if (!fq) {
        fq = create_frag_queue(user, skb);
        if (!fq) {
            kfree_skb(skb);
            return prev_skb;
        }
    }

    if (queue_skb(fq, skb)) {
        if (fq->complete) {
            return reassemble_skb(fq);
        } else {
            return prev_skb;
        }
    }

    release_frag_queue(fq);
    return prev_skb;
}

struct sk_buff *ipv6_frag_gather(struct sk_buff *skb, u32 user)
{
    struct sk_buff *prev_skb;

    if (ipv6_hdr(skb)->payload_len == 0)
        return skb;

    prev_skb = find_prev_fragment(skb);
    if (!prev_skb)
        return skb;

    skb = skb_clone(skb, GFP_ATOMIC);
    if (!skb)
        return skb;

    if (skb_headroom(skb) < sizeof(struct ipv6hdr)) {
        kfree_skb(skb);
        return skb;
    }

    skb_set_transport_header(skb, sizeof(struct ipv6hdr));

    if (check_mem_threshold(skb)) {
        kfree_skb(skb);
        return skb;
    }

    struct frag_queue *fq = find_or_create_frag_queue(user);
    if (!fq) {
        kfree_skb(skb);
        return skb;
    }

    if (queue_skb(fq, skb)) {
        struct sk_buff *reassembled_skb = reassemble_frags(fq);
        if (reassembled_skb)
            return reassembled_skb;
    }

    release_frag_queue(fq);
    return skb;
}

struct sk_buff *ipv6_gather_frags(struct sk_buff *skb, u32 user) {
    if (!skb->len) {
        return skb;
    }

    struct sk_buff *prev_skb = NULL;
    int prev_hdr;

    if ((prev_hdr = ipv6_find_prev_hdr(skb, &prev_skb)) < 0) {
        return skb;
    }

    skb = skb_clone(skb, GFP_ATOMIC);
    if (!skb || skb->len < skb->data_len) {
        kfree_skb(skb);
        return prev_skb;
    }

    skb_set_transport_header(skb, prev_hdr);
    if (skb->data_len > sysctl_max_frag_mem) {
        kfree_skb(skb);
        return prev_skb;
    }

    struct frag_queue *fq;
    if ((fq = frag_find_queue(user)) == NULL) {
        fq = frag_create_queue(user);
        if (!fq) {
            kfree_skb(skb);
            return prev_skb;
        }
    }

    if (frag_queue_skb(fq, skb) < 0) {
        frag_release_queue(fq);
        return prev_skb;
    }

    if (!frag_queue_complete(fq)) {
        return prev_skb;
    }

    skb = frag_reassemble(fq);
    frag_release_queue(fq);

    return skb;
}

struct sk_buff *ipv6_gather_frags(struct sk_buff *skb, u32 user) {
    if (skb->len == 0)
        return skb;

    struct sk_buff *prev_skb = NULL;
    struct sk_buff *clone_skb = skb_clone(skb, GFP_ATOMIC);
    if (!clone_skb || skb_headroom(clone_skb) < skb_headroom(skb)) {
        kfree_skb(clone_skb);
        return skb;
    }

    skb_set_transport_header(clone_skb, skb_transport_offset(skb));

    struct frag_queue *fq = find_frag_queue(user);
    if (!fq) {
        fq = create_frag_queue(user);
        if (!fq) {
            kfree_skb(clone_skb);
            return skb;
        }
    }

    if (queue_skb(fq, clone_skb)) {
        if (is_all_fragments_received(fq)) {
            struct sk_buff *reassembled_skb = reassemble_skb(fq);
            if (reassembled_skb)
                return reassembled_skb;
        }
    }

    release_frag_queue(fq);
    return skb;
}

struct sk_buff *ipv6_gather_frags(struct sk_buff *skb, u32 user) {
    if (skb->len == 0)
        return skb;

    struct iphdr *iph = ip_hdr(skb);
    struct sk_buff *prev_skb = NULL;

    if (prev_skb) {
        struct sk_buff *clone = skb_clone(skb, GFP_ATOMIC);
        if (!clone || clone->len < skb->len)
            return skb;

        skb_set_transport_header(clone, skb->transport_header);
        if (atomic_read(&clone->truesize) > sysctl_wmem_max)
            return skb;

        struct frag_queue *fq = find_frag_queue(user, iph->id);
        if (!fq) {
            fq = create_frag_queue(user, iph->id);
            if (!fq)
                return skb;
        }

        if (queue_skb(fq, clone) < 0)
            return skb;

        if (fq->all_fragments_received) {
            struct sk_buff *reassembled = reassemble_skb(fq);
            if (reassembled)
                return reassembled;
        }

        release_frag_queue(fq);
    }

    return skb;
}
